from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class GetVswrBandInfo(SchemaObject):
    vswr = SchemaField(name='vswr', not_null=True)
    bands = SchemaField(name='bands', many=True, optional=True)

    def __init__(self, vswr, bands):
        self.vswr = vswr
        self.bands = bands

        super(GetVswrBandInfo, self).__init__()
